import React, { useState, useEffect } from "react";
import RoomGrid from "../components/RoomGrid";
import BookingControls from "../components/BookingControls";

const HomePage = () => {
  const [rooms, setRooms] = useState([]);

  useEffect(() => {
    fetch("http://localhost:5000/api/bookings/rooms")
      .then((res) => res.json())
      .then((data) => {
        if (Array.isArray(data)) {
          setRooms(data);
        } else {
          console.error("Invalid response: Expected an array", data);
          setRooms([]);
        }
      })
      .catch((err) => {
        console.error("Error fetching rooms:", err);
        setRooms([]);
      });
  }, []);

  const bookRooms = (count) => {
    fetch("http://localhost:5000/api/bookings/book", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ count }),
    })
      .then((res) => res.json())
      .then((data) => {
        alert(`Booked Rooms: ${data.bookedRooms.join(", ")}`);
        fetch("http://localhost:5000/api/bookings/rooms")
          .then((res) => res.json())
          .then((data) => setRooms(data));
      });
  };

  const randomizeRooms = () => {
    fetch("http://localhost:5000/api/bookings/randomize", { method: "POST" })
      .then(() => fetch("http://localhost:5000/api/bookings/rooms"))
      .then((res) => res.json())
      .then((data) => setRooms(data));
  };

  const resetRooms = () => {
    fetch("http://localhost:5000/api/bookings/reset", { method: "POST" })
      .then((res) => res.json())
      .then((data) => {
        console.log("Rooms after reset:", data.rooms);
        setRooms(data.rooms);
      })
      .catch((err) => console.error("Failed to reset rooms:", err));
  };

  return (
    <div className="flex flex-col min-h-screen">
      {/* Header */}
      <header className="bg-blue-600 text-white text-center py-4 shadow-md">
        <h1 className="text-3xl font-semibold">Hotel Booking System</h1>
      </header>

      {/* Main Content */}
      <main className="flex flex-col items-center justify-center flex-grow p-6">
        <div className="bg-white shadow-lg rounded-lg p-6 w-full max-w-2xl text-center">
          <h2 className="text-2xl font-bold mb-4">Book Your Room</h2>
          <BookingControls
            bookRooms={bookRooms}
            randomizeRooms={randomizeRooms}
            resetRooms={resetRooms}
          />
        </div>

        <div className="mt-6 w-full max-w-4xl">
          <RoomGrid rooms={rooms} />
        </div>
      </main>

      {/* Footer */}
      <footer className="bg-gray-800 text-white text-center py-4 mt-6">
        <p>© 2025 Hotel Booking. All rights reserved.</p>
      </footer>
    </div>
  );
};

export default HomePage;
